mapper.select:
/* AppLeaveFlowMapper.searchApprovers */ SELECT U.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , FNC_CMM_INFO_SRCH(U.CMPNY_CD, 'BAIM_VAL', U.RANK_CD, 'COM007') AS rankNm , FNC_CMM_INFO_SRCH(U.CMPNY_CD, 'NODE', U.SITE_CD, U.NODE_CD) AS nodeNm FROM TB_USER U LEFT JOIN TB_BAIM_VAL_D D ON D.CMPNY_CD = U.CMPNY_CD AND D.BAIM_VAL_CD = 'COM007' AND D.BAIM_VAL_D_CD = U.RANK_CD AND D.USE_YN = 'Y' WHERE U.CMPNY_CD = #{cmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y' AND U.WITHDRAWAL_DATE IS NULL AND U.ACCOUNT_STATUS = '01' AND U.USER_CD != #{excludeUserCd} AND U.AUTH_CD != 'system'
AND U.USER_NM LIKE CONCAT('%', #{keyword}, '%')
ORDER BY (D.SORT_IDX IS NULL), D.SORT_IDX ASC, U.USER_NM ASC, U.USER_CD ASC LIMIT #{limit} OFFSET #{offset}

/* AppLeaveFlowMapper.countValidApprovers */
SELECT COUNT(DISTINCT U.USER_CD)
  FROM TB_USER U
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.SITE_CD  = #{siteCd}
   AND U.USE_YN   = 'Y'
   AND U.WITHDRAWAL_DATE IS NULL
   AND U.ACCOUNT_STATUS  = '01'
   AND U.AUTH_CD != 'system'
   AND U.USER_CD IN

     #{uc}

/* AppLeaveFlowMapper.countAttendanceByDate */
SELECT COUNT(1)
  FROM TB_USER_ATTD_MGMT A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.SITE_CD  = #{siteCd}
   AND A.USER_CD  = #{userCd}
   AND A.WORK_YMD = #{workYmd}
   AND A.DEL_YN   = 'N'

/* AppLeaveFlowMapper.selectOccupiedLeaveDaysOnDate */
SELECT COALESCE(SUM(
         CASE WHEN U.USE_UNIT_TYPE = '00' THEN 1.0 ELSE U.LEAVE_DAYS END
       ), 0)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD     = #{cmpnyCd}
   AND U.USER_CD      = #{userCd}
   AND U.LEAVE_STATUS = 'CONFIRMED'
   AND U.DEL_YN       = 'N'
   AND U.START_DATE   <=  #{workYmd}
   AND U.END_DATE     >=  #{workYmd}

/* AppLeaveFlowMapper.selectDeductibleGrantsForRange */
SELECT
      G.GRANT_ID        AS grantId
    , G.GRANT_DAYS      AS grantDays
    , G.USED_DAYS       AS usedDays
    , G.AVAIL_FROM_DATE AS availFromDate
    , G.AVAIL_TO_DATE   AS availToDate
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.USER_CD  = #{userCd}
   AND G.LEAVE_CD = #{leaveCd}
   AND G.DEL_YN   = 'N'
   AND G.STATUS   = 'ACTIVE'
   AND (G.GRANT_DAYS - G.USED_DAYS)  >  0

   AND G.AVAIL_FROM_DATE  <=  #{toYmd}
   AND G.AVAIL_TO_DATE    >=  #{fromYmd}
 ORDER BY G.AVAIL_TO_DATE ASC, G.GRANT_DATE ASC, G.GRANT_ID ASC

/* AppLeaveFlowMapper.selectTotalUsedDays */
SELECT IFNULL(SUM(U.LEAVE_DAYS), 0)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD     = #{cmpnyCd}
   AND U.USER_CD      = #{userCd}
   AND U.LEAVE_CD     = #{leaveCd}
   AND U.LEAVE_STATUS = 'CONFIRMED'
   AND U.DEL_YN       = 'N'

/* AppLeaveFlowMapper.selectFiscalUsedDays */
SELECT IFNULL(SUM(U.LEAVE_DAYS), 0)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD     = #{cmpnyCd}
   AND U.USER_CD      = #{userCd}
   AND U.LEAVE_CD     = #{leaveCd}
   AND U.LEAVE_STATUS = 'CONFIRMED'
   AND U.DEL_YN       = 'N'
   AND U.START_DATE  >= #{fiscalStartYmd}
   AND U.START_DATE  <  #{fiscalEndYmdExclusive}

/* AppLeaveFlowMapper.selectDeductibleGrant */
SELECT
      G.GRANT_ID   AS grantId
    , G.GRANT_DAYS AS grantDays
    , G.USED_DAYS  AS usedDays
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.USER_CD  = #{userCd}
   AND G.LEAVE_CD = #{leaveCd}
   AND G.DEL_YN   = 'N'
   AND G.STATUS   = 'ACTIVE'
   AND G.AVAIL_FROM_DATE <= #{workYmd}
   AND G.AVAIL_TO_DATE   >= #{workYmd}
   AND (G.GRANT_DAYS - G.USED_DAYS) >= #{neededDays}
 ORDER BY G.AVAIL_TO_DATE ASC, G.GRANT_DATE ASC
 LIMIT 1
 FOR UPDATE

