/* AppLeaveFlowMapper.insertLeaveReq */
INSERT INTO TB_USER_ATTD_REQ (
      REQ_ID
    , CMPNY_CD
    , SITE_CD
    , USER_CD
    , REQ_TYPE
    , REQ_STATUS
    , REQ_REASON
    , WORK_YMD
    , NODE_CD
    , START_DATE
    , START_TIME
    , END_DATE
    , END_TIME
    , LEAVE_TYPE
    , LEAVE_DAYS

    , LEAVE_GROUP_ID
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{reqId}
    , #{cmpnyCd}
    , #{siteCd}
    , #{userCd}
    , '05'
    , #{reqStatus}
    , #{reqReason}
    , #{workYmd}
    , #{nodeCd}
    , #{startDate}
    , #{startTime}
    , #{endDate}
    , #{endTime}
    , #{leaveType}
    , #{leaveDays}
    , #{leaveGroupId}
    , 'N'
    , #{insertNo}
    , NOW()
)

/* AppLeaveFlowMapper.insertLeaveUse */
INSERT INTO TB_USER_LEAVE_USE (
      LEAVE_ID
    , CMPNY_CD
    , SITE_CD
    , USER_CD
    , LEAVE_CD
    , REQ_ID
    , GRANT_ID
    , START_DATE
    , START_TIME
    , END_DATE
    , END_TIME
    , USE_UNIT_TYPE
    , LEAVE_DAYS
    , LEAVE_MINUTES
    , LEAVE_REASON
    , EVIDENCE_FILE_ID
    , LEAVE_STATUS
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{leaveId}
    , #{cmpnyCd}
    , #{siteCd}
    , #{userCd}
    , #{leaveCd}
    , #{reqId}
    , #{grantId}
    , #{startDate}
    , #{startTime}
    , #{endDate}
    , #{endTime}
    , #{useUnitType}
    , #{leaveDays}
    , #{leaveMinutes}
    , #{leaveReason}
    , #{evidenceFileId}
    , #{leaveStatus}
    , 'N'
    , #{insertNo}
    , NOW()
)

mapper.update:
/* AppLeaveFlowMapper.recomputeGrantUsedDays */
UPDATE TB_USER_LEAVE_GRANT G
   SET G.USED_DAYS = IFNULL((
           SELECT SUM(U.LEAVE_DAYS)
             FROM TB_USER_LEAVE_USE U
            WHERE U.CMPNY_CD     = G.CMPNY_CD
              AND U.GRANT_ID     = G.GRANT_ID
              AND U.LEAVE_STATUS = 'CONFIRMED'
              AND U.DEL_YN       = 'N'
       ), 0)
     , G.UPDATE_NO   = #{updateNo}
     , G.UPDATE_DATE = NOW()
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.GRANT_ID = #{grantId}

