/* AppLeaveFlowMapper.selectUserHireDate */
SELECT U.HIRE_DATE
  FROM TB_USER U
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.USER_CD  = #{userCd}
   AND U.USE_YN   = 'Y'
   AND U.WITHDRAWAL_DATE IS NULL
 LIMIT 1

/* AppLeaveFlowMapper.selectDeductibleGrants */
SELECT
      G.GRANT_ID   AS grantId
    , G.GRANT_DAYS AS grantDays
    , G.USED_DAYS  AS usedDays
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.USER_CD  = #{userCd}
   AND G.LEAVE_CD = #{leaveCd}
   AND G.DEL_YN   = 'N'
   AND G.STATUS   = 'ACTIVE'
   AND G.AVAIL_FROM_DATE <= #{workYmd}
   AND G.AVAIL_TO_DATE   >= #{workYmd}
   AND (G.GRANT_DAYS - G.USED_DAYS) > 0
 ORDER BY G.AVAIL_TO_DATE ASC, G.GRANT_DATE ASC, G.GRANT_ID ASC
 FOR UPDATE

/* AppLeaveFlowMapper.selectDeductibleRemainingSum */
SELECT COALESCE(SUM(G.GRANT_DAYS - G.USED_DAYS), 0)
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.USER_CD  = #{userCd}
   AND G.LEAVE_CD = #{leaveCd}
   AND G.DEL_YN   = 'N'
   AND G.STATUS   = 'ACTIVE'
   AND G.AVAIL_FROM_DATE <= #{workYmd}
   AND G.AVAIL_TO_DATE   >= #{workYmd}
   AND (G.GRANT_DAYS - G.USED_DAYS) > 0

/* AppLeaveFlowMapper.countGrantsValidOnDate */
SELECT COUNT(*)
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.USER_CD  = #{userCd}
   AND G.LEAVE_CD = #{leaveCd}
   AND G.DEL_YN   = 'N'
   AND G.STATUS   = 'ACTIVE'
   AND G.AVAIL_FROM_DATE <= #{workYmd}
   AND G.AVAIL_TO_DATE   >= #{workYmd}

/* AppLeaveFlowMapper.selectMinAvailFromAfterDate */
SELECT MIN(G.AVAIL_FROM_DATE)
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.USER_CD  = #{userCd}
   AND G.LEAVE_CD = #{leaveCd}
   AND G.DEL_YN   = 'N'
   AND G.STATUS   = 'ACTIVE'
   AND G.AVAIL_FROM_DATE > #{workYmd}

/* AppLeaveFlowMapper.selectBorrowDeductibleGrants */
SELECT
      G.GRANT_ID   AS grantId
    , G.GRANT_DAYS AS grantDays
    , G.USED_DAYS  AS usedDays
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.USER_CD  = #{userCd}
   AND G.LEAVE_CD = #{leaveCd}
   AND G.DEL_YN   = 'N'
   AND G.STATUS   = 'ACTIVE'
   AND G.AVAIL_FROM_DATE <= #{workYmd}
   AND G.AVAIL_TO_DATE   >= #{workYmd}
   AND (G.GRANT_DAYS - G.USED_DAYS) > 0
 ORDER BY G.AVAIL_TO_DATE ASC, G.GRANT_DATE ASC
 FOR UPDATE

