/* AppLeaveFlowMapper.selectEvidenceFileOwner */
SELECT F.INSERT_NO
  FROM TB_FILE_INFO F
 WHERE F.CMPNY_CD     = #{cmpnyCd}
   AND F.FILE_MGMT_CD = #{fileMgmtCd}
   AND F.FILE_TYPE    = '008'
 LIMIT 1

/* AppLeaveFlowMapper.countValidEvidenceFile */
SELECT COUNT(1)
  FROM TB_FILE_INFO F
 WHERE F.CMPNY_CD     = #{cmpnyCd}
   AND F.FILE_MGMT_CD = #{fileMgmtCd}
   AND F.FILE_TYPE    = '008'
   AND F.INSERT_NO    = #{userCd}
